namespace thesis_jaco_perception { namespace {
constexpr double kEps=1e-12;
MeshPoint3 sub(MeshPoint3 a,MeshPoint3 b){return {a.x-b.x,a.y-b.y,a.z-b.z};} MeshPoint3 add(MeshPoint3 a,MeshPoint3 b){return {a.x+b.x,a.y+b.y,a.z+b.z};} MeshPoint3 mul(MeshPoint3 a,double s){return {a.x*s,a.y*s,a.z*s};} MeshPoint3 cross(MeshPoint3 a,MeshPoint3 b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};} double dot(MeshPoint3 a,MeshPoint3 b){return a.x*b.x+a.y*b.y+a.z*b.z;} double norm(MeshPoint3 a){return std::sqrt(dot(a,a));}
MeshPoint3 xf(const std::array<double,16>&m,MeshPoint3 p){return {m[0]*p.x+m[1]*p.y+m[2]*p.z+m[3],m[4]*p.x+m[5]*p.y+m[6]*p.z+m[7],m[8]*p.x+m[9]*p.y+m[10]*p.z+m[11]};}
bool rigid(const std::array<double,16>&m){for(double v:m)if(!std::isfinite(v))return false;if(std::abs(m[12])+std::abs(m[13])+std::abs(m[14])>1e-9||std::abs(m[15]-1)>1e-9)return false;for(int i=0;i<3;++i)for(int j=0;j<3;++j){double s=0;for(int k=0;k<3;++k)s+=m[k*4+i]*m[k*4+j];if(std::abs(s-(i==j))>1e-6)return false;}return m[0]*(m[5]*m[10]-m[6]*m[9])-m[1]*(m[4]*m[10]-m[6]*m[8])+m[2]*(m[4]*m[9]-m[5]*m[8])>0;}
std::array<double,16> invrigid(const std::array<double,16>&m){if(!rigid(m))throw std::invalid_argument("world_link is not a finite rigid transform");std::array<double,16>r{m[0],m[4],m[8],0,m[1],m[5],m[9],0,m[2],m[6],m[10],0,0,0,0,1};r[3]=-(r[0]*m[3]+r[1]*m[7]+r[2]*m[11]);r[7]=-(r[4]*m[3]+r[5]*m[7]+r[6]*m[11]);r[11]=-(r[8]*m[3]+r[9]*m[7]+r[10]*m[11]);return r;}
double hit(MeshPoint3 o,MeshPoint3 d,const MeshTriangle&t){auto e1=sub(t.b,t.a),e2=sub(t.c,t.a),p=cross(d,e2);double det=dot(e1,p);if(std::abs(det)<kEps)return -1;double inv=1/det,u=dot(sub(o,t.a),p)*inv;if(u<0||u>1)return -1;auto q=cross(sub(o,t.a),e1);double v=dot(d,q)*inv;if(v<0||u+v>1)return -1;double s=dot(e2,q)*inv;return s>kEps?s:-1;}
MeshAabb empty(){double x=std::numeric_limits<double>::infinity();return {{x,x,x},{-x,-x,-x}};} void extend(MeshAabb*b,MeshPoint3 p){b->min={std::min(b->min.x,p.x),std::min(b->min.y,p.y),std::min(b->min.z,p.z)};b->max={std::max(b->max.x,p.x),std::max(b->max.y,p.y),std::max(b->max.z,p.z)};} MeshAabb box(const MeshTriangle&t){auto b=empty();extend(&b,t.a);extend(&b,t.b);extend(&b,t.c);return b;}
bool boxhit(const MeshAabb&b,MeshPoint3 o,MeshPoint3 d,double best){double lo=0,hi=best;for(int i=0;i<3;++i){double ov=i?i==1?o.y:o.z:o.x,dv=i?i==1?d.y:d.z:d.x,mn=i?i==1?b.min.y:b.min.z:b.min.x,mx=i?i==1?b.max.y:b.max.z:b.max.x;if(std::abs(dv)<kEps){if(ov<mn||ov>mx)return false;}else{double a=(mn-ov)/dv,z=(mx-ov)/dv;if(a>z)std::swap(a,z);lo=std::max(lo,a);hi=std::min(hi,z);if(lo>hi)return false;}}return true;}
int make_bvh(MeshInstance*m,std::size_t first,std::size_t count){int id=m->bvh.size();m->bvh.push_back({empty(),-1,-1,first,count});MeshAabb cb=empty();for(std::size_t i=first;i<first+count;++i){auto&t=m->triangles[m->bvh_indices[i]];auto b=box(t);extend(&m->bvh[id].bounds,b.min);extend(&m->bvh[id].bounds,b.max);extend(&cb,mul(add(add(t.a,t.b),t.c),1./3));}if(count<=8)return id;double dx=cb.max.x-cb.min.x,dy=cb.max.y-cb.min.y,dz=cb.max.z-cb.min.z;int axis=dy>dx&&dy>=dz?1:dz>dx?2:0;auto mid=first+count/2;auto coord=[&](std::size_t i){auto&t=m->triangles[i];auto c=mul(add(add(t.a,t.b),t.c),1./3);return axis==0?c.x:axis==1?c.y:c.z;};std::nth_element(m->bvh_indices.begin()+first,m->bvh_indices.begin()+mid,m->bvh_indices.begin()+first+count,[&](auto a,auto b){double ca=coord(a),cb=coord(b);return ca==cb?a<b:ca<cb;});int left=make_bvh(m,first,mid-first);int right=make_bvh(m,mid,count-(mid-first));m->bvh[id].left=left;m->bvh[id].right=right;m->bvh[id].count=0;return id;}
std::array<double,16> pose(const urdf::Pose&p){double r,q,y;p.rotation.getRPY(r,q,y);double cr=cos(r),sr=sin(r),cp=cos(q),sp=sin(q),cy=cos(y),sy=sin(y);return {cy*cp,cy*sp*sr-sy*cr,cy*sp*cr+sy*sr,p.position.x,sy*cp,sy*sp*sr+cy*cr,sy*sp*cr-cy*sr,p.position.y,-sp,cp*sr,cp*cr,p.position.z,0,0,0,1};}
MeshAabb world_box(const MeshAabb & b,const std::array<double,16>&m){auto out=empty();for(int x=0;x<2;++x)for(int y=0;y<2;++y)for(int z=0;z<2;++z)extend(&out,xf(m,{x?b.max.x:b.min.x,y?b.max.y:b.min.y,z?b.max.z:b.min.z}));return out;}
std::optional<MeshRayResult> bvh_profile(const MeshInstance&m,const MeshPoint3&c,const MeshPoint3&p,MeshQueryProfile*profile){auto d=sub(p,c);double r=norm(d);if(r<=kEps)throw std::invalid_argument("null ray");d=mul(d,1/r);double best=std::numeric_limits<double>::infinity();std::vector<int>stack{0};while(!stack.empty()){auto id=stack.back();stack.pop_back();if(profile){++profile->bvh_nodes;++profile->node_aabbs;}auto&n=m.bvh[id];if(!boxhit(n.bounds,c,d,best))continue;if(n.count){if(profile)++profile->bvh_leaves;for(std::size_t i=n.first;i<n.first+n.count;++i){if(profile)++profile->triangles;double s=hit(c,d,m.triangles[m.bvh_indices[i]]);if(s>0&&s<best)best=s;}}else{stack.push_back(n.left);stack.push_back(n.right);}}if(!std::isfinite(best))return {};return MeshRayResult{best,r-best,0};}
}}
namespace thesis_jaco_perception {
bool is_finite(const MeshPoint3&p){return std::isfinite(p.x)&&std::isfinite(p.y)&&std::isfinite(p.z);} bool is_non_degenerate(const MeshTriangle&t){return is_finite(t.a)&&is_finite(t.b)&&is_finite(t.c)&&norm(cross(sub(t.b,t.a),sub(t.c,t.a)))>kEps;}
MeshTriangle transform_triangle(const MeshTriangle&t,const double m[16]){if(!is_non_degenerate(t))throw std::invalid_argument("degenerate triangle");std::array<double,16>a;for(int i=0;i<16;++i)a[i]=m[i];return {xf(a,t.a),xf(a,t.b),xf(a,t.c),t.link_index};}
std::optional<MeshRayResult> first_mesh_intersection(const std::vector<MeshTriangle>&ts,const MeshPoint3&c,const MeshPoint3&p){if(ts.empty()||!is_finite(c)||!is_finite(p))throw std::invalid_argument("empty mesh or non-finite point");auto d=sub(p,c);double r=norm(d);if(r<=kEps)throw std::invalid_argument("null ray");d=mul(d,1/r);std::optional<MeshRayResult>b;for(auto&t:ts){if(!is_non_degenerate(t))throw std::invalid_argument("degenerate triangle");double s=hit(c,d,t);if(s>0&&(!b||s<b->distance))b=MeshRayResult{s,r-s,t.link_index};}return b;}
MeshClassification classify_mesh_observation(const std::vector<MeshTriangle>&ts,const MeshPoint3&c,const MeshPoint3&p,double e){if(!std::isfinite(e)||e<0)throw std::invalid_argument("invalid epsilon");auto h=first_mesh_intersection(ts,c,p);if(!h||h->delta_ray<-e)return MeshClassification::EXTERNAL_CONFIRMED;if(std::abs(h->delta_ray)<=e)return MeshClassification::SELF_CONFIRMED;return MeshClassification::OCCLUDED_UNKNOWN;} MeshProvenance collision_mesh_provenance(){return {true,true,"collision_mesh"};} MeshProvenance visual_shadow_only_provenance(){return {true,true,"visual_shadow_only"};}
std::string resolve_thesis_collision_uri(const std::string&u){const std::string p="package://thesis_description/";if(u.rfind(p,0)!=0)throw std::invalid_argument("collision URI must be inside thesis_description");auto relative=std::filesystem::path(u.substr(p.size())).lexically_normal();if(relative.empty()||relative.is_absolute()||relative.string().rfind("..",0)==0)throw std::invalid_argument("collision URI escapes package");auto path=std::filesystem::path(ament_index_cpp::get_package_share_directory("thesis_description"))/relative;if(!std::filesystem::is_regular_file(path))throw std::invalid_argument("collision URI does not resolve to existing package file");return path.string();}
void build_mesh_bvh(MeshInstance*m){if(!m||m->triangles.empty())throw std::invalid_argument("empty mesh");for(auto&t:m->triangles)if(!is_non_degenerate(t))throw std::invalid_argument("invalid mesh triangle");m->bvh_indices.resize(m->triangles.size());for(std::size_t i=0;i<m->triangles.size();++i)m->bvh_indices[i]=i;m->bvh.clear();make_bvh(m,0,m->triangles.size());}
std::vector<MeshInstance> load_collision_meshes_from_urdf_xml(const std::string&xml){auto model=urdf::parseURDF(xml);if(!model)throw std::invalid_argument("invalid URDF XML");std::vector<MeshInstance>out;for(auto&entry:model->links_){auto link=entry.second;for(auto&c:link->collision_array){auto mesh=std::dynamic_pointer_cast<urdf::Mesh>(c->geometry);if(!mesh)continue;auto&s=mesh->scale;if(!std::isfinite(s.x)||!std::isfinite(s.y)||!std::isfinite(s.z)||s.x<=0||s.y<=0||s.z<=0)throw std::invalid_argument("invalid collision mesh scale");MeshInstance in{link->name,mesh->filename,pose(c->origin),{}, {},{},collision_mesh_provenance()};Assimp::Importer imp;auto scene=imp.ReadFile(resolve_thesis_collision_uri(mesh->filename),aiProcess_Triangulate|aiProcess_JoinIdenticalVertices|aiProcess_PreTransformVertices);if(!scene||!scene->HasMeshes())throw std::invalid_argument("Assimp could not load collision DAE");for(unsigned mi=0;mi<scene->mNumMeshes;++mi)for(unsigned f=0;f<scene->mMeshes[mi]->mNumFaces;++f){auto&face=scene->mMeshes[mi]->mFaces[f];if(face.mNumIndices!=3)throw std::invalid_argument("non-triangulable Assimp face");MeshPoint3 v[3];for(int k=0;k<3;++k){auto&a=scene->mMeshes[mi]->mVertices[face.mIndices[k]];v[k]=xf(in.local_collision_transform,{a.x*s.x,a.y*s.y,a.z*s.z});if(!is_finite(v[k]))throw std::invalid_argument("non-finite mesh vertex");}in.triangles.push_back({v[0],v[1],v[2],out.size()});}if(in.triangles.empty())throw std::invalid_argument("empty collision mesh");build_mesh_bvh(&in);out.push_back(std::move(in));}}if(out.empty())throw std::invalid_argument("URDF contains no collision meshes");return out;}
std::optional<MeshRayResult> first_bvh_intersection(const MeshInstance&m,const MeshPoint3&c,const MeshPoint3&p){if(m.bvh.empty()||!is_finite(c)||!is_finite(p))throw std::invalid_argument("empty BVH or non-finite ray");auto d=sub(p,c);double r=norm(d);if(r<=kEps)throw std::invalid_argument("null ray");d=mul(d,1/r);double best=std::numeric_limits<double>::infinity();std::vector<int>stack{0};while(!stack.empty()){auto id=stack.back();stack.pop_back();auto&n=m.bvh[id];if(!boxhit(n.bounds,c,d,best))continue;if(n.count)for(std::size_t i=n.first;i<n.first+n.count;++i){double s=hit(c,d,m.triangles[m.bvh_indices[i]]);if(s>0&&s<best)best=s;}else{stack.push_back(n.left);stack.push_back(n.right);}}if(!std::isfinite(best))return {};return MeshRayResult{best,r-best,0};}
std::optional<MeshWorldRayResult> first_world_mesh_intersection(const std::vector<MeshInstance>&ms,const std::vector<MeshLinkTransform>&ts,const MeshPoint3&c,const MeshPoint3&p){if(!is_finite(c)||!is_finite(p))throw std::invalid_argument("non-finite world ray");std::optional<MeshWorldRayResult>b;for(auto&m:ms){auto it=std::find_if(ts.begin(),ts.end(),[&](auto&t){return t.link_frame==m.link_frame;});if(it==ts.end())throw std::invalid_argument("missing world_link transform");auto h=first_bvh_intersection(m,xf(invrigid(it->world_link),c),xf(invrigid(it->world_link),p));if(h&&(!b||h->distance<b->distance))b=MeshWorldRayResult{h->distance,h->delta_ray,m.link_frame,m.uri};}return b;}
std::vector<MeshWorldInstance> update_world_mesh_instances(const std::vector<MeshInstance>&ms,const std::vector<MeshLinkTransform>&ts,MeshQueryProfile*profile){auto begin=std::chrono::steady_clock::now();std::vector<MeshWorldInstance>out;for(auto&m:ms){auto it=std::find_if(ts.begin(),ts.end(),[&](auto&t){return t.link_frame==m.link_frame;});if(it==ts.end())throw std::invalid_argument("missing world_link transform");if(!rigid(it->world_link)||m.bvh.empty())throw std::invalid_argument("invalid world mesh instance");out.push_back({&m,*it,world_box(m.bvh.front().bounds,it->world_link)});}if(profile)profile->world_aabb_update_ms+=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();return out;}
std::optional<MeshWorldRayResult> first_world_mesh_intersection_brute_force(const std::vector<MeshWorldInstance>&is,const MeshPoint3&c,const MeshPoint3&p){if(!is_finite(c)||!is_finite(p))throw std::invalid_argument("non-finite world ray");std::optional<MeshWorldRayResult>b;for(auto&i:is){auto inv=invrigid(i.transform.world_link);auto h=first_mesh_intersection(i.mesh->triangles,xf(inv,c),xf(inv,p));if(h&&(!b||h->distance<b->distance))b=MeshWorldRayResult{h->distance,h->delta_ray,i.mesh->link_frame,i.mesh->uri};}return b;}
std::optional<MeshWorldRayResult> first_world_mesh_intersection_optimized(const std::vector<MeshWorldInstance>&is,const MeshPoint3&c,const MeshPoint3&p,double e,MeshQueryProfile*profile){if(!is_finite(c)||!is_finite(p)||!std::isfinite(e)||e<0)throw std::invalid_argument("invalid optimized query");auto begin=std::chrono::steady_clock::now();auto d=sub(p,c);double r=norm(d);if(r<=kEps)throw std::invalid_argument("null ray");d=mul(d,1/r);if(profile)++profile->rays;std::optional<MeshWorldRayResult>b;for(auto&i:is){if(profile)++profile->link_aabbs;if(!boxhit(i.world_aabb,c,d,r+e)){if(profile)++profile->links_rejected;continue;}if(profile)++profile->links_to_bvh;auto inv=invrigid(i.transform.world_link);auto h=bvh_profile(*i.mesh,xf(inv,c),xf(inv,p),profile);if(h&&(!b||h->distance<b->distance))b=MeshWorldRayResult{h->distance,h->delta_ray,i.mesh->link_frame,i.mesh->uri};}if(profile)profile->query_ms+=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();return b;}
}
